<style>
/* UI per Maura's Figma bar (Group 1256, 870 px wide): every size is in design units (u) that scale with the figure. */
:root{
  --page:#1a1a1a; --stage:#232323; --ink:#ffffff; --ink-2:#a3a3a3; --ink-3:#6f6f6f; --rule:#343434; --track:#3a3a3a;
  --mono:"IBM Plex Mono",ui-monospace,"SFMono-Regular",Menlo,Consolas,monospace;
  color-scheme:dark;
}
html,body{background:var(--page);color:var(--ink)}
body{font-family:var(--mono);padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));padding-block:16px;-webkit-tap-highlight-color:transparent}
.fig{width:min(720px,100%);aspect-ratio:720/920;margin:0 auto;background:var(--stage);display:flex;flex-direction:column;overflow:hidden;container-type:inline-size;
  --pad:16px; --u:calc((100cqw - 2*var(--pad))/870)}
.scene{position:relative;overflow:hidden;flex:1 1 0;min-height:0;background:url(data:image/png;base64,),linear-gradient(#252524 0,#262625 55%,#1d1d1c 100%)}
canvas{display:block;width:100%;height:100%;object-fit:contain}
.portrait{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:68% 38%;pointer-events:none;background:#1d1d1c;transform-origin:68% 38%;will-change:opacity,transform}
.load[hidden],.bigplay[hidden]{display:none}
.load{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:12px;padding:12px 18px;border-radius:999px;background:rgba(12,12,14,.78);font-size:11px;letter-spacing:.1em;color:#fff;text-transform:uppercase;white-space:nowrap;z-index:5}
.load .sp{width:16px;height:16px;border-radius:50%;border:2px solid rgba(255,255,255,.28);border-top-color:#fff;animation:ldspin .8s linear infinite}
@keyframes ldspin{to{transform:rotate(360deg)}}

/* big play over the picture: plain white disc, like the bar's play button */
.bigplay{position:absolute;left:50%;top:50%;width:clamp(56px,calc(146*var(--u)),76px);aspect-ratio:1;transform:translate(-50%,-50%);border:0;border-radius:50%;
  background:var(--ink);color:#111;display:grid;place-items:center;cursor:pointer;box-shadow:0 6px 30px rgba(0,0,0,.35);transition:transform .18s ease,box-shadow .18s ease}
.bigplay svg{width:42%;height:42%}
.bigplay:hover{transform:translate(-50%,-50%) scale(1.06);box-shadow:0 8px 36px rgba(0,0,0,.45)}
.bigplay:active{transform:translate(-50%,-50%) scale(.96)}

/* caption */
.cap{flex:0 0 auto;box-sizing:border-box;padding:calc(18*var(--u) + 6px) calc(var(--pad) + 8*var(--u)) 0;height:calc(150*var(--u) + 24px);overflow:hidden}
.cap h3{margin:0 0 calc(12*var(--u));font:600 max(12px,calc(18.6*var(--u)))/1.2 var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--ink)}
.cap p{margin:0;max-width:72ch;font:400 max(12px,calc(18.6*var(--u)))/1.3 var(--mono);color:var(--ink);text-wrap:pretty}

/* transport bar: timeline on its own full-width row; play + time left, utilities right */
.transport{flex:0 0 auto;display:grid;grid-template-columns:auto 1fr auto auto auto;grid-template-areas:"track track track track track" "play clock restart speed mute";align-items:center;
  column-gap:8px;row-gap:calc(6*var(--u) + 4px);padding:calc(4*var(--u)) var(--pad) calc(14*var(--u) + 10px)}
.ib{--s:34px;position:relative;width:var(--s);height:var(--s);border-radius:50%;border:1.5px solid var(--track);background:transparent;color:var(--ink-2);
  display:grid;place-items:center;cursor:pointer;padding:0;transition:color .15s,border-color .15s,background .15s,transform .12s}
.ib::before{content:"";position:absolute;inset:calc((var(--s) - 44px)/2)}
.ib svg{width:62%;height:62%;overflow:visible} .ib.play svg{width:42%;height:42%}
.ib:hover{border-color:var(--ink-3)}
.ib:active{transform:scale(.94)}
.ib.play{--s:40px;background:var(--ink);border-color:var(--ink);color:#111}
#play{grid-area:play} #restart{grid-area:restart} #mute{grid-area:mute} #speed{grid-area:speed} .clock{grid-area:clock}
.ib.spd{font:600 11px/1 var(--mono);letter-spacing:-.02em;font-variant-numeric:tabular-nums}
@media (hover:hover){.ib:hover,.ib.play:hover,.bigplay:hover{color:#8D4CF6}}

.scene::after{content:"";position:absolute;inset:0;z-index:1;background:#8D4CF6;mix-blend-mode:multiply;opacity:0;pointer-events:none;transition:opacity .4s ease}
.bigplay{z-index:2}
@media (hover:hover){
  .scene:has(.bigplay:not([hidden])):hover::after{opacity:.85}
  .scene:has(.bigplay:not([hidden])){cursor:pointer}
  .scene:has(.bigplay:not([hidden])):hover .bigplay{color:#8D4CF6;transform:translate(-50%,-50%) scale(1.06);box-shadow:0 8px 36px rgba(0,0,0,.45)}
}
.bigplay:focus-visible,.ib:focus-visible,.chapters button:focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.track{grid-area:track;min-width:0;position:relative}
.rail{position:relative;height:24px}
.bar{position:absolute;left:0;right:0;top:50%;height:max(3px,calc(4*var(--u)));transform:translateY(-50%);border-radius:2px;overflow:hidden;pointer-events:none}
.bar i{position:absolute;top:0;bottom:0;background:var(--track)}
.bar{overflow:visible}
.bar i{border-radius:2px;overflow:hidden}
.bar em,.bar u{position:absolute;left:0;top:0;bottom:0;width:0}
.bar em{background:var(--ink-2)} .bar u{background:rgba(255,255,255,.14)}
#scrub{-webkit-appearance:none;appearance:none;position:absolute;inset:0;width:100%;height:100%;margin:0;background:transparent;cursor:pointer;touch-action:none;
  --k:13px}
#scrub::-webkit-slider-runnable-track{height:100%;background:transparent}
#scrub::-moz-range-track{height:100%;background:transparent}
#scrub::-webkit-slider-thumb{-webkit-appearance:none;width:var(--k);height:var(--k);border-radius:50%;background:var(--ink);border:0;margin-top:calc((24px - var(--k))/2);transition:transform .15s;box-shadow:0 0 0 0 rgba(255,255,255,.18)}
#scrub::-moz-range-thumb{width:var(--k);height:var(--k);border-radius:50%;background:var(--ink);border:0;transition:transform .15s}
#scrub:hover::-webkit-slider-thumb,#scrub:active::-webkit-slider-thumb{transform:scale(1.25)}
#scrub:hover::-moz-range-thumb,#scrub:active::-moz-range-thumb{transform:scale(1.25)}
#scrub:focus-visible::-webkit-slider-thumb{box-shadow:0 0 0 3px var(--stage),0 0 0 5px var(--ink)}
.tip{position:absolute;bottom:calc(100% - 4px);transform:translateX(-50%);padding:5px 8px;border-radius:6px;background:#fff;color:#111;font:400 11px/1 var(--mono);white-space:nowrap;pointer-events:none;opacity:0;transition:opacity .12s}
.tip.on{opacity:1}
.chapters{position:relative;height:16px;margin-top:2px;font:400 11px/16px var(--mono);color:var(--ink-3)}
@container (max-width:380px){.chapters{font-size:10px;letter-spacing:-.02em}}
.chapters button{position:absolute;top:0;padding:4px 0;margin-top:-4px;border:0;background:none;color:inherit;font:inherit;cursor:pointer;white-space:nowrap;transition:color .15s}
.chapters button:hover{color:var(--ink)}
.chapters button.on{color:var(--ink-2)}
.clock{display:flex;align-items:center;padding:0 4px;font:400 11px/1 var(--mono);color:var(--ink-2);font-variant-numeric:tabular-nums;white-space:nowrap}
.src{max-width:720px;margin:10px auto 0;font-size:11px;line-height:1.5;color:var(--ink-2)}
@media (hover:none){.tip{display:none}}

/* phone: whole widget on one screen; timeline gets its own row, buttons under it */
@media (max-width:560px){
  html,body{overflow:hidden;height:100%} body{padding-block:8px;padding-left:max(8px,env(safe-area-inset-left,0px));padding-right:max(8px,env(safe-area-inset-right,0px))}
  .fig{--pad:14px;--u:.6px;aspect-ratio:auto;height:calc(100vh - 16px);height:calc(100dvh - 16px)}
  .scene{flex:1 1 0;min-height:0;max-height:calc(100cqw*853/720)}
  .cap{height:118px;padding:14px var(--pad) 0;margin-bottom:auto}
  .cap h3{font-size:13px;margin-bottom:8px} .cap p{font-size:13px;line-height:1.36}
  .transport{row-gap:8px;column-gap:10px;padding:0 var(--pad) 14px}
  .ib{--s:38px} .ib.play{--s:44px}
}
@media (max-width:380px){ .ib{--s:36px} .ib.play{--s:42px} .transport{column-gap:8px} }

</style>

<!-- Open Brain book: everything in this block is the book's, not the author's. -->
<style>
:root{
  --page:var(--ob-plate,#1a1a1a);
  --mono:var(--ob-font-mono,"IBM Plex Mono",ui-monospace,"SFMono-Regular",Menlo,Consolas,monospace);
}
/* Figure pane: the frame is as tall as the pane allows (--ob-max-height); the scene takes
   what the caption and transport leave, and the canvas script redraws to its box. */
html[data-ob-fit],html[data-ob-fit] body{height:100%;overflow:hidden}
html[data-ob-fit] .fig{width:100%;aspect-ratio:auto;height:var(--ob-max-height,100vh);max-height:100vh}
/* v5 (OPENBRAIN-55): type uses CSS pixels, not the artwork's design units.
   Reserve enough caption space for its longest timed passage without spending
   150 design units on every short line; the drawing gets the remaining height. */
html[data-ob-book] .cap{height:auto;min-height:126px;padding:14px var(--pad) 8px;overflow:visible}
html[data-ob-book] .cap h3{font-size:14px;line-height:1.3;margin-bottom:8px}
html[data-ob-book] .cap p{font-size:16px;line-height:1.4}
html[data-ob-book] .chapters{font-size:13px;line-height:20px;height:20px;letter-spacing:0;color:var(--ink-2)}
html[data-ob-book] .clock,html[data-ob-book] .ib.spd{font-size:13px}
html[data-ob-book] .transport{padding-bottom:14px;row-gap:8px}
@media (max-width:560px){
  html[data-ob-book] .cap{min-height:148px}
  /* Equal cells keep the last two timeline labels apart in the narrow pane
     and inline on phones; the scrub bar retains the author's timed segments. */
  html[data-ob-book] .chapters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));height:auto;font-size:12px}
  html[data-ob-book] .chapters button{position:static;padding:4px 0;margin:0;font:inherit;white-space:normal;overflow-wrap:anywhere;text-align:left}
  html[data-ob-book] .chapters button:last-child{text-align:right}
}
html[data-ob-fit] .scene{flex:1 1 0!important;aspect-ratio:auto!important;min-height:0;max-height:none}
/* Inline in the book (no pane): the frame grows to the content, so nothing may size
   itself from the viewport. On a phone the scene keeps the artwork's 720 x 853. */
@media (max-width:560px){
  html[data-ob-book]:not([data-ob-fit]),html[data-ob-book]:not([data-ob-fit]) body{height:auto;overflow:visible}
  html[data-ob-book]:not([data-ob-fit]) .fig{height:auto}
  html[data-ob-book]:not([data-ob-fit]) .scene{flex:none!important;aspect-ratio:720/853!important;max-height:none}
}
@media (prefers-reduced-motion:reduce){.load .sp{animation:none}}
html[data-ob-reduce-motion] .load .sp{animation:none}
/* Maura, 18 Nov: the hover tooltip with the time and section is redundant. */
.tip{display:none!important}
</style>
<script>
if(window.OB){
  document.documentElement.setAttribute("data-ob-book","");
  /* The period/step heading is drawn into the canvas by the author. Its
     12.5 design-unit cap becomes ~5px on a short pane. Adapt only that
     heading's paint, leaving the artwork, coordinates and player untouched.
     Account for object-fit:contain as well as the backing-store transform. */
  document.addEventListener("DOMContentLoaded",()=>{
    const canvas=document.getElementById("cv"), context=canvas.getContext("2d"), fillText=context.fillText;
    context.fillText=function(text,x,y,...rest){
      if(!document.documentElement.hasAttribute("data-ob-fit")||this.textAlign!=="left"||y>=100) return fillText.call(this,text,x,y,...rest);
      const font=this.font, size=font.match(/([\d.]+)px/), matrix=this.getTransform();
      const scale=Math.min(canvas.clientWidth/canvas.width,canvas.clientHeight/canvas.height)*Math.hypot(matrix.c,matrix.d);
      if(!size||!scale) return fillText.call(this,text,x,y,...rest);
      this.save();
      this.font=font.replace(/([\d.]+)px/,Math.max(Number(size[1]),13/scale)+"px");
      fillText.call(this,text,x,y,...rest);
      this.restore();
    };
    /* A paused frame must repaint after its caption or the pane resizes too. */
    new ResizeObserver(()=>{
      if(document.documentElement.hasAttribute("data-ob-fit")&&document.getElementById("load").hidden) window.__w?.render(window.__w.t);
    }).observe(canvas);
  });
}
</script>

