  ctx.fillStyle="#717171"; ctx.fill(STEM); ctx.beginPath(); ctx.arc(212-DX,643,6,0,7); ctx.fill();
  ctx.fillStyle="#191818"; ctx.beginPath(); ctx.arc(212-DX,643,2.45,0,7); ctx.fill(); ctx.beginPath(); ctx.arc(211.94-DX,660.45,1.47,0,7); ctx.fill();

  ctx.save(); ctx.translate(0,-AY); ctx.fillStyle="rgba(0,0,0,.4)"; ctx.fillRect(-OXU-10,700,CW+20,160); ctx.restore();
  segBegin("strip"); ctx.translate(0,-AY);
  // Loewi's record: what is still to come stays dim; the cursor reveals it
  const part2=t>=TL.T2, rx=cursorX(t), cx=stripX(rx), showCur=t>=TL.curAt;
  const X0=-OXU, SW=CW, SX=SW/714, mx=x=>X0+x*SX;
  ctx.save(); ctx.translate(X0,0); ctx.scale(SX,1);
  ctx.drawImage(I.unr,4,0,I.unr.width-4,I.unr.height,4,725,I.unr.width-4,I.unr.height);
  { const ra=Math.min(sstep(82.255-.1,82.255+.5,t),1-sstep(85.886-.2,85.886+.7,t)); if(ra>.003){ ctx.save(); ctx.globalAlpha=ra; if(WL.complete&&WL.naturalWidth) ctx.drawImage(WL,0,725,714,I.unr.height); ctx.restore(); } }
  if(part2){ ctx.save(); ctx.beginPath(); ctx.rect(0,725,cx,140); ctx.clip(); ctx.drawImage(I.rev,0,725); ctx.restore(); }
  ctx.restore();
  { const SL=["RINGER'S","VAGUS","NORMAL","VAGUS","+ ATROPINE"], curA=showCur?sstep(TL.curAt,TL.curAt+.35,t):0, sc=showCur?(part2?secOf(rx):0):-1;
    ctx.save(); ctx.font=labelFont(); try{ ctx.letterSpacing=labelLS()+"px"; }catch(e){} ctx.textAlign="center"; ctx.textBaseline="alphabetic";
    for(let k=0;k<5;k++){ const g=A.gray[k], gw=I["g"+k].width, w=ctx.measureText(SL[k]).width;
      let x=mx(g[0]+gw/2), a=.2;
      if(k<sc) a=lerp(.2,.5,curA);
      else if(k===sc){ a=lerp(.2,1,curA); x=lerp(x,mx(cx),curA); }
      x=clamp(x,X0+14+w/2,X0+SW-14-w/2); ctx.fillStyle=`rgba(255,255,255,${a})`; ctx.fillText(SL[k],x+labelLS()/2,720); }
    ctx.restore(); }
  if(showCur){ ctx.save(); ctx.globalAlpha=sstep(TL.curAt,TL.curAt+.35,t); ctx.fillStyle="#fff"; ctx.fillRect(Math.min(mx(cx),X0+SW-2),727,2,126); ctx.restore(); }

  segEnd(); ctx.setTransform(S,0,0,S,OXU*S,0);
  if(foc&&!window.__noFocus) drawFocus(t);
  // film grain over the artwork, as in the sketch
  if(!window.__noFocus) grainPass();
  // period tag (top left): progress ring and title before Figure 1, then what is in the heart
  let tag=null; for(const g of TL.tags) if(t>=g[0]-.3 && t<g[1]+.6) tag=g;
  let tagA=0, label="", ring=null, dot=null;
  if(tag){ tagA=clamp(Math.min(t-tag[0]+.3,tag[1]+.6-t)/.3,0,1); label=(tag[2]+" · "+tag[3]).toUpperCase(); ring=clamp((t-tag[0])/(tag[1]-tag[0]),0,1); }
  else if(part2){ tagA=clamp((t-TL.T2)/.4,0,1); const s=secOf(rx); label=SECTS[s][1].toUpperCase(); dot=hex(SECTS[s][2]); }
  tagA*=1-sstep(143.542,144.092,t);
  if(tagA>0){ const kk=CW/(cv.getBoundingClientRect().width||CW), pd=(matchMedia("(max-width:560px)").matches?14:16)*kk, TX=pd-OXU+12.5, TY=pd+12.5-AY;
    ctx.save(); ctx.globalAlpha=tagA;
    if(ring!==null){ ctx.strokeStyle="rgba(255,255,255,.22)"; ctx.lineWidth=3; ctx.beginPath(); ctx.arc(TX,TY,11,0,7); ctx.stroke();
      ctx.strokeStyle="#fff"; ctx.beginPath(); ctx.arc(TX,TY,11,-Math.PI/2,-Math.PI/2+ring*2*Math.PI); ctx.stroke(); }
    if(dot){ ctx.fillStyle=rgb(dot); ctx.beginPath(); ctx.arc(TX,TY,9,0,7); ctx.fill(); }
    ctx.fillStyle="#fff"; ctx.textAlign="left"; ctx.font=labelFont(); try{ ctx.letterSpacing=labelLS()+"px"; }catch(e){} ctx.fillText(label,TX+20,TY+4); ctx.restore(); }

}

/* ---------------- transport (as in the original) ---------------- */
let RATE=1; const audio=new Audio(); let trackSet=false; let curSeg=null, t=0, playing=false, last=0, muted=false, unlocked=false, blocked=false;
const segAt = t => { for(const s of TL.segs) if(t>=s.t0 && t<s.t0+s.dur) return s; return null; };
const splitCap = s => { const x=s.text; if(x.length<=170) return [x]; const mid=x.length/2; let best=-1,bd=1e9;
  for(let i=0;i<x.length-1;i++){ if(/[.?!]/.test(x[i]) && x[i+1]===" "){ const d=Math.abs(i-mid); if(d<bd){ bd=d; best=i+1; } } }
  if(best<0) for(let i=0;i<x.length-1;i++){ if(/[:;,]/.test(x[i]) && x[i+1]===" "){ const d=Math.abs(i-mid); if(d<bd){ bd=d; best=i+1; } } }
  if(best<0) return [x]; return [x.slice(0,best).trim(), x.slice(best).trim()]; };
const captionAt = t => { let c=null; for(const s of TL.segs) if(t>=s.t0-.15) c=s; if(!c) return c; if(c.cap) return {text:c.cap}; if(c.ns) return c; const p=splitCap(c); if(p.length<2) return c;
  const CUTS={p3a:9.93};   // seconds into each clip where the narrator pauses between the two parts
  const cutT = CUTS[c.id]!=null ? CUTS[c.id] : c.dur*p[0].length/(p[0].length+p[1].length); return {text: (t-c.t0)<cutT?p[0]:p[1]}; };
function unlock(){ if(unlocked) return; unlocked=true; try{ if(!trackSet){ audio.src=A.track; trackSet=true; } audio.muted=muted; try{ audio.currentTime=t; }catch(e){} const p=audio.play(); if(p&&p.catch) p.catch(()=>{}); }catch(e){} }
function syncAudio(){
  if(!playing){ if(!audio.paused) audio.pause(); return; }
  if(blocked) return;
  if(!trackSet){ audio.src=A.track; trackSet=true; }
  if(audio.paused){ try{ audio.currentTime=t; }catch(e){} audio.muted=muted; const p=audio.play(); if(p&&p.then) p.then(()=>{ blocked=false; }).catch(e=>{ if(e&&e.name==="NotAllowedError"){ blocked=true; } }); }
  else if(audio.readyState>0 && Math.abs(audio.currentTime-t)>.4){ try{ audio.currentTime=t; }catch(e){} } }
const PORT_OUT=7.7;
function paintUI(){ { const pe=$("portrait"); if(pe){ const o=1-sstep(PORT_OUT-.9,PORT_OUT,t); pe.style.opacity=o; pe.style.display=o<=0?"none":"block"; pe.style.transform="scale("+(1+.09*Math.min(1,t/PORT_OUT))+")"; } } const c=captionAt(t); $("caph").textContent = t<CH[1][1] ? "The set-up" : t<CH[2][1] ? "Collecting" : t<CH[3][1] ? "Recording" : "Conclusion";
  $("cap").textContent = blocked&&playing ? "Your browser blocked the narration. Tap the sound button to start it." : (c?c.text:"Otto Loewi, Graz, 1921: does a nerve act on the heart directly, or through a chemical?");
  $("scrub").value=t; if(segFill) segFill(t,"em"); $("scrub").setAttribute("aria-valuetext",mmss(t)+" of "+mmss(TL.total)+", "+chapAt(t));
  { const ci=chapIdx(t); if(ci!==window.__ci){ window.__ci=ci; [...$("chapters").children].forEach((b,i)=>b.classList.toggle("on",i===ci)); } } $("clock").textContent=mmss(t)+" / "+mmss(TL.total); }
function frame(now){ if(playing){ const dt=last?Math.min(.1,(now-last)/1000):0; last=now; t=Math.min(TL.total,t+dt*RATE); if(t>=TL.total) setPlaying(false); }
  if(audio.currentTime!==window.__lct){ window.__lct=audio.currentTime; window.__lcn=now; }
  if(playing && trackSet && !audio.paused && audio.readyState>=2 && now-(window.__lcn||0)<400){ const dA=audio.currentTime-t; if(Math.abs(dA)<1.5) t = Math.abs(dA)>.25 ? audio.currentTime : t+dA*.2; }
  if(window.__cap30 && playing && (now-(window.__ld||0))<28){ syncAudio(); requestAnimationFrame(frame); return; } window.__ld=now;
  const r0=performance.now(); render(t); const rd=performance.now()-r0; window.__pn=(window.__pn||0)+1; window.__pa=window.__pa==null?rd:window.__pa*.92+rd*.08;
  if(playing && window.__pn>45 && S>1 && window.__pa>12 && !window.__s1){ window.__s1=true; S=1; HPX=853; applyScale(); window.__pa=8; window.__pn=0; }
  if(playing && window.__pn>45){ if(!window.__lite && window.__pa>14) window.__lite=true; else if(window.__lite && !window.__cap30 && window.__pa>17) window.__cap30=true; }
  syncAudio(); paintUI(); if(playing) requestAnimationFrame(frame); }
function setPlaying(p){ playing=p; last=0; if(p){ unlock(); syncAudio(); }
  $("play-i").setAttribute("d", p ? "M18.4 119.6h3.6a.6 .6 0 0 1 .6.6v14.8a.6 .6 0 0 1-.6.6h-3.6a.6 .6 0 0 1-.6-.6V120.2a.6 .6 0 0 1 .6-.6ZM26.4 119.6h3.6a.6 .6 0 0 1 .6.6v14.8a.6 .6 0 0 1-.6.6h-3.6a.6 .6 0 0 1-.6-.6V120.2a.6 .6 0 0 1 .6-.6Z" : "M17.2969 119.77C17.2969 118.658 18.5037 117.965 19.4646 118.525L32.5981 126.186C33.5516 126.743 33.5516 128.12 32.5981 128.677L19.4646 136.338C18.5037 136.898 17.2969 136.205 17.2969 135.093V119.77Z"); $("play").title = p ? "Pause (space)" : "Play (space)";
  $("play").setAttribute("aria-label", p ? "Pause" : (t>=TL.total-.05 ? "Replay" : "Play"));
  $("bigplay").hidden = p || (t>0 && t<TL.total-.05); $("bigplay").setAttribute("aria-label", t>=TL.total-.05 ? "Watch again" : "Play narrated animation");
  if(!p){ audio.pause(); curSeg=null; } requestAnimationFrame(frame); }
function seek(x){ t=clamp(x,0,TL.total); curSeg=null; if(!playing) $("bigplay").hidden=t>0; requestAnimationFrame(frame); }
function toggle(){ if(!playing && t>=TL.total-.05) t=0; setPlaying(!playing); }
const chapIdx=x=>{ let k=0; CH.forEach(([,at],i)=>{ if(x>=at-.01) k=i; }); return k; };
const chapAt=x=>CH[chapIdx(x)][0];
CH.forEach(([name,at],i)=>{ const b=document.createElement("button"); b.type="button"; b.textContent=name; b.setAttribute("aria-label","Jump to "+name); if(i===CH.length-1) b.style.right="0"; else b.style.left=(100*at/TL.total)+"%";
  b.addEventListener("click",()=>{ seek(at); if(!playing) setPlaying(true); }); $("chapters").appendChild(b);
  const seg=document.createElement("i"), end=i<CH.length-1?CH[i+1][1]:TL.total; seg.style.left=`calc(${100*at/TL.total}% + ${i?1.5:0}px)`; seg.style.width=`calc(${100*(end-at)/TL.total}% - ${i?1.5:0}px - ${i<CH.length-1?1.5:0}px)`;
  seg.dataset.a=at; seg.dataset.b=end; seg.innerHTML="<em></em><u></u>"; $("bar").appendChild(seg); });
var SEGS=[...document.querySelectorAll("#bar i")], segFill=(x,sel)=>SEGS.forEach(g=>{ g.querySelector(sel).style.width=(100*clamp((x-g.dataset.a)/(g.dataset.b-g.dataset.a),0,1))+"%"; });
// hover preview: time + chapter
{ const sc=$("scrub"), tip=$("tip");
  const at=e=>{ const r=sc.getBoundingClientRect(); return clamp((e.clientX-r.left)/r.width,0,1); };
  sc.addEventListener("pointermove",e=>{ if(e.pointerType!=="mouse") return; const f=at(e), x=f*TL.total; tip.textContent=mmss(x)+" · "+chapAt(x); tip.style.left=(100*f)+"%"; tip.classList.add("on"); segFill(x,"u"); });
  sc.addEventListener("pointerleave",()=>{ tip.classList.remove("on"); segFill(-1,"u"); });
  sc.addEventListener("keydown",e=>{ const d={ArrowRight:5,ArrowUp:5,ArrowLeft:-5,ArrowDown:-5,PageUp:15,PageDown:-15}[e.key]; if(d){ e.preventDefault(); seek(t+d); } else if(e.key==="Home"){ e.preventDefault(); seek(0); } else if(e.key==="End"){ e.preventDefault(); seek(TL.total); } }); }
$("play").addEventListener("click",toggle); $("bigplay").addEventListener("click",toggle); document.querySelector(".scene").addEventListener("click",e=>{ if(!$("bigplay").hidden && !e.target.closest("button")) toggle(); });
$("restart").addEventListener("click",()=>{ t=0; curSeg=null; setPlaying(true); });
$("scrub").max=TL.total; $("scrub").addEventListener("input",e=>seek(+e.target.value));
$("mute").addEventListener("click",()=>{ if(blocked){ blocked=false; muted=false; unlocked=false; unlock(); curSeg=null; syncAudio(); } else { muted=!muted; audio.muted=muted; }
  $("mute-on").style.display=muted?"none":""; $("mute-off").style.display=muted?"":"none"; $("mute").setAttribute("aria-pressed",String(muted)); $("mute").setAttribute("aria-label",muted?"Unmute":"Mute"); $("mute").title=muted?"Unmute (M)":"Mute (M)"; });
document.addEventListener("keydown",e=>{ if(e.metaKey||e.ctrlKey||e.altKey) return; const k=e.key.toLowerCase(); const onCtl=e.target.closest("input,button");
  if((k===" "&&!onCtl)||k==="k"){ e.preventDefault(); toggle(); } else if(k==="m"){ $("mute").click(); } else if(!onCtl&&(k==="arrowright"||k==="l")){ e.preventDefault(); seek(t+5); } else if(!onCtl&&(k==="arrowleft"||k==="j")){ e.preventDefault(); seek(t-5); } });
{ const R=[1,1.5,2]; $("speed").addEventListener("click",()=>{ RATE=R[(R.indexOf(RATE)+1)%R.length]; try{ audio.defaultPlaybackRate=RATE; audio.playbackRate=RATE; audio.preservesPitch=true; }catch(e){}
  $("speed").textContent=RATE+"×"; $("speed").setAttribute("aria-label","Playback speed: "+RATE+"×"); }); }
audio.addEventListener("loadedmetadata",()=>{ try{ audio.playbackRate=RATE; }catch(e){} });
window.__w={ seek, render, TL, get t(){return t} };
loadAll().then(()=>{ $("load").hidden=true; $("bigplay").hidden=false; render(0); paintUI(); });

(()=>{ const scene=document.querySelector(".scene"); if(!scene||!window.ResizeObserver) return;
  const fit=()=>{ const w=scene.clientWidth, h=scene.clientHeight; if(!w||!h) return; const cw=Math.round(Math.max(720,Math.min(1000,853*w/h)));
    if(cw===CW) return; CW=cw; OXU=(CW-720)/2-ART_DX; applyScale(); try{ render(t); }catch(e){} };
  new ResizeObserver(fit).observe(scene); fit(); })();
</script>

</body></html>$w$;
BEGIN
  SELECT html INTO prior_html FROM public.widget_uploads
    WHERE slug = 'loewi-vagusstoff' FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Loewi v5: upload missing; apply prerequisite migrations first';
  END IF;
  IF prior_html = next_html THEN RETURN; END IF;
  IF md5(prior_html) <> 'bcbafa32e37aeb7ef144349a0890fd02' THEN
    RAISE EXCEPTION 'Loewi v5: upload differs from the expected baseline; review before reupload';
  END IF;
  UPDATE public.widget_uploads SET html = next_html, updated_at = now()
   WHERE slug = 'loewi-vagusstoff';
END
$v5$;
